// ─── À RENSEIGNER APRÈS L'IMPORT ────────────────────────────────────
// Seul node à modifier : tout le reste du workflow lit ces valeurs.
//
// Le node est traversant — il recopie ses items d'entrée en y ajoutant
// les paramètres — pour ne pas écraser les items du déclencheur.
const PARAMETRES = {
  // Numéro long code français acheté chez Twilio, au format E.164.
  expediteur: '+33600000000',

  // Identifiant de la conversation Telegram — destinataire UNIQUE.
  // Les conseillers ne reçoivent rien (cahier des charges §6, WF-5 bis).
  chat_id: '000000000',

  // Agenda principal de Romain — celui qui porte aussi le sport et le BNI.
  agenda: 'primary',

  // Boîte dédiée au dépôt des pièces, distincte de la boîte générale.
  mail_pieces: 'pieces@era-dupontromain.fr',

  // Ollama sur le VPS. Ne JAMAIS pointer un modèle « :cloud » ici :
  // le texte contient nom, revenus et situation d'un candidat.
  ollama: 'http://127.0.0.1:11434/api/generate',
  modele: 'qwen2.5:3b-instruct-q4_K_M',
};

const entree = $input.all();
return (entree.length ? entree : [{ json: {} }])
  .map((item) => ({ json: { ...item.json, ...PARAMETRES } }));

// Prépare la lecture d'agenda. Renvoyer zéro item arrête proprement la
// branche : c'est le cas d'un SMS venu d'un numéro inconnu, ou d'une
// séquence déjà close.
const contexte = $input.first().json;
const parametres = $('Paramètres').first().json;

const corps = $('Webhook Twilio').first().json;
const recu = corps.body || corps;
const texte = String(recu.Body || '').trim();
const numero = String(recu.From || '');

if (!contexte.candidat) {
  // Personne ne répond dans le vide : le message est remonté tel quel.
  return [{
    json: {
      __sans_candidat: true,
      chat_id: parametres.chat_id,
      texte: ['<b>SMS reçu hors séquence</b>', `De : ${numero}`, `« ${texte} »`].join('\n'),
    },
  }];
}

// Fenêtre de lecture large : le J+2 ouvré peut tomber loin quand la
// demande arrive un jeudi et qu'un pont suit.
const maintenant = new Date();
const fin = new Date(maintenant.getTime() + 40 * 86400000);

return [{
  json: {
    agenda: parametres.agenda,
    fenetre_debut: maintenant.toISOString(),
    fenetre_fin: fin.toISOString(),
    texte_recu: texte,
  },
}];

// ===== Socle ERA — généré par n8n/bundle.js, ne pas modifier ici =====
// Régénérer avec : npm run n8n:build
const ERA = (function () {
  const __d = {};
  const __c = {};
  function __require(id) {
    const cle = String(id).replace(/^\.\//, '').replace(/\.js$/, '');
    if (__c[cle]) return __c[cle].exports;
    if (!__d[cle]) throw new Error("Module absent du socle : " + id);
    const module = { exports: {} };
    __c[cle] = module;
    __d[cle](module, module.exports, __require);
    return module.exports;
  }
