  FUSEAU,
  JOURS_OUVRES,
  PLAGE_ENVOI,
  DELAI_MINI_JOURS_OUVRES,
  BLOCAGE_HEURES_OUVREES,
  RELANCES_MAX,
  ECHECS_PARSING_MAX,
  ARBITRAGE_RAPPEL_JOURS,
  ARBITRAGE_ATTENTE_JOURS,
  ARBITRAGE_ATTENTE_ABSENCE_JOURS,
